import Foundation

/// Authored context for the retained, graph-specific example launchers.
@MainActor enum LayerLegacyExampleLessonCopy {
    struct Copy {let purpose:String;let open:String;let path:String;let change:String;let question:String}
    static let examples:[String:Copy]=[
        "gelu":.init(purpose:"A smooth activation can reduce a negative feature without clipping it to zero. Compare exact GELU with its tanh approximation on the same kind of classifier graph.",open:"Open exact GELU example or Open approximate GELU example",path:"The model projects six hidden values, arranges them into two groups of three, applies GELU and returns them to the classifier's feature row. The final Linear produces class scores. Data preparation and Train supply the separate Training/Validation experiment.",change:"Select Activation and inspect Function GELU and Approximation. Compare Exact with Tanh approximation, applying and running a deliberate change. Predict a negative and a positive response before inspecting captured values. A changed architecture can retrain different weights, so separate the activation's local rule from final classifier quality.",question:"Why is Tanh alone not GELU's tanh approximation? Why may a small negative GELU input remain negative?"),
        "softmax-example":.init(purpose:"Which scores should compete? Softmax turns each chosen group into shares adding to one, and the chosen axis determines that group.",open:"Open Softmax example",path:"The model arranges six learned scores into two rows of three, applies Softmax, then uses a final Linear to produce the class scores used for training. Softmax's intermediate shares are distinct from the final classifier output.",change:"Select Activation with Softmax. Compare the normalization axis for three scores within each row with the first sample direction for two scores within each column. Apply and run each choice, then check the appropriate group sums in the captured tensor. Keep batch/observation direction 0 separate.",question:"Why does one score change the other shares in its group? Why would summing all six values obscure which normalization was configured?"),
        "norm-example":.init(purpose:"The normalization group changes the meaning of a result. Compare two three-value groups with a single six-value group inside each observation.",open:"Open grouped LayerNorm example or Open whole-sample LayerNorm example",path:"The model arranges six learned features into a two-by-three sample. Normalization uses the selected trailing shape, with learned scale/bias before GELU and the classifier. Preprocess separately learns Training-table statistics; Layer normalization recomputes summaries within each observation.",change:"Select Normalization with Layer method and inspect its trailing dimensions. Run the supplied grouped example first, then save before opening the whole-sample example. Compare the captured grouping, values and parameter shapes. Do not infer that changing the normalization scope preserves the old learned state.",question:"Which other values can affect one normalized feature? Why is this not the same operation as fitting a scaler on the whole Training table?"),
        "embedding-example":.init(purpose:"Category IDs can select useful learned vectors without treating category number 3 as three times category number 1.",open:"Open embedding example",path:"The synthetic table repeats category combinations. Integer model inputs select lookup-table rows, the paired representation is flattened and a classifier learns two class scores. These repeated combinations demonstrate shared lookup weights; they do not establish generalization to unseen categories.",change:"Inspect the integer category IDs, Embedding's table size/vector width and the captured selected vectors after running. Trace repeated IDs to their shared row. Compare Train's held-out predictions separately. An unknown or out-of-range ID needs an explicit repair; it is not automatically another category.",question:"Which values are selectors and which values are learned? Why can two observations reuse the same table row without mixing their identities?"),
        "bilinear-example":.init(purpose:"Two sets of features can interact pair by pair. Bilinear learns how those pairs contribute, rather than merely appending the two rows.",open:"Open bilinear example",path:"The two model paths produce feature operands for Bilinear. Its learned interaction weights combine them, with optional bias, before the final classifier. The data path keeps preparation and Training/Validation separate.",change:"Run the supplied graph, then select Bilinear. Inspect its two input widths, output width and bias choice, plus Weights and biases. Compare captured input/output shapes and a few actual values. Keep observation/grouping dimensions compatible; changing a width requires compatible parameters and later layers.",question:"How does a feature-pair interaction differ from Add or Concatenate? Which weights are shared across observations?"),
        "lazy-linear":.init(purpose:"A builder may want the next layer to determine its incoming feature width from the previous tensor. Inferred-width Linear creates compatible parameters once; it does not learn the width from a target label.",open:"Open inferred-width example",path:"The supplied classifier uses Linear with Input sizing set to Infer from input. Its connected feature direction determines input width; output features and bias remain explicit choices. Train adjusts the created weights using the prepared Training table.",change:"Run the supplied graph and inspect Linear's inferred width, parameter inventory and captured output. Compare a repeat/reopen with the same compatible source. A changed width or sizing mode needs compatible fresh state; existing saved weights must not silently stretch or shrink.",question:"Why should a batch-size change not change the layer's input width? How is initialization different from the later training updates?"),
        "separable":.init(purpose:"Filtering spatially and mixing channels can be separated into two visible calculations. This makes a useful small container for inspecting both steps.",open:"Open separable convolution example",path:"The Separable container first applies independent per-channel spatial filters, then a one-position convolution mixes the resulting channels. Expand its main-canvas frame to see the same child components and connections. Its channels are constructed numeric features, not imported photographs.",change:"Run the unchanged example. Expand the container and inspect both child shapes. Change its exposed multiplier from two to three, Apply and inspect the derived input width of the channel-mixing child before rerunning. Preserve its output channel count. Releasing a derived binding makes you responsible for compatible child settings.",question:"Which stage mixes channels and which filters them independently? Why can the intermediate width change while the final width stays fixed?"),
        "depthwise":.init(purpose:"A spatial pattern can be learned independently for each channel before another operation mixes channels. Depthwise convolution makes that separation explicit.",open:"Open depthwise convolution example",path:"The synthetic classifier constructs a small multichannel grid. Depthwise Convolution applies a separate filter to each input channel, with a multiplier deciding how many outputs each channel produces. Later layers turn the result into class scores.",change:"Run the supplied graph and record output channels and parameter count. Select the depthwise Convolution and try changing its multiplier from two to one. Check the resulting channel count and downstream flattened input width; repair that width or Undo before running a compatible graph.",question:"Why does a larger multiplier add filters without mixing input channels? What later operation could combine information across those channels?"),
        "transpose1d":transposed("line","length","Open transposed convolution example"),
        "transpose2d":transposed("grid","height and width","Open spatial transposed convolution example"),
        "transpose3d":transposed("volume","depth, height and width","Open volume transposed convolution example")
    ]
    private static func transposed(_ layout:String,_ dimensions:String,_ button:String)->Copy {
        .init(purpose:"Transposed convolution spreads learned contributions into an output \(layout) and adds overlaps. Its output geometry is useful for expanding a representation; it is not a general inverse that restores lost information.",open:button,path:"The supplied classifier constructs a numeric \(layout) from table features, applies the transposed convolution and prepares its result for class scores. Read \(dimensions) separately from channels and observation count. These are synthetic features, not a recorded image, scan or sound.",change:"Run the unchanged example and record its output shape. Select Convolution with the transposed operation and inspect output padding. Reduce a nonzero output-padding setting in one direction, Apply and check the downstream width before rerunning. Undo if you want to restore the original architecture. Output padding selects extent; it does not append input measurements.",question:"Where do contributions overlap? Which output direction changed? Why does a larger output alone not establish recovered information or better prediction?")
    }
    static func steps(_ id:String)->[LessonContentStep]? {
        guard let copy=examples[id] else {return nil}
        return [
            LessonContent.step("goal","Meet the example model",copy.purpose+"\n\nA fresh lesson canvas opens without the completed example. Use “"+copy.open+"” in Exercise choices & reference to load it, saving existing work first.\n\n"+copy.path),
            LessonContent.step("build","Run the supplied model first","1. Open the named example below.\n2. Follow prepared tables into Train and tensors through the model.\n3. Run Flow with the supplied settings.\n4. Select the featured operation and inspect its captured Output.\n\nA sample shape describes one observation; the leading batch count describes how many observations are processed together. Planned shapes are configuration metadata, not measured values.",kind:.canvasAction),
            LessonContent.step("example.change","Change and compare",copy.change,kind:.canvasAction),
            LessonContent.step("inspect","Check your understanding",copy.question+"\n\nThis editable example is unscored. Compare actual captured evidence and Train's Validation predictions separately; a valid tensor shape is not a prediction-quality result. Separate Construction assessments retain their own task identities and completion receipts.",kind:.question)
        ]
    }
}
